1170	func (s *Server) setupRPC() error {
1171		s.rpcConnLimiter.SetConfig(connlimit.Config{
1172			MaxConnsPerClientIP: s.config.RPCMaxConnsPerClient,
1173		})
1174	
1175		for _, fn := range endpoints {
1176			s.rpcServer.Register(fn(s))
1177		}
1178	
1179		// Only register AutoEncrypt on the insecure RPC server. Insecure only
1180		// means that verify incoming is turned off even though it might have
1181		// been configured.
1182		s.insecureRPCServer.Register(&AutoEncrypt{srv: s})
1183	
1184		// Setup the AutoConfig JWT Authorizer
1185		var authz AutoConfigAuthorizer
1186		if s.config.AutoConfigAuthzEnabled {
1187			// create the auto config authorizer from the JWT authmethod
1188			validator, err := ssoauth.NewValidator(s.logger, &s.config.AutoConfigAuthzAuthMethod)
1189			if err != nil {
1190				return fmt.Errorf("Failed to initialize JWT Auto Config Authorizer: %w", err)
1191			}
1192	
1193			authz = &jwtAuthorizer{
1194				validator:       validator,
1195				allowReuse:      s.config.AutoConfigAuthzAllowReuse,
1196				claimAssertions: s.config.AutoConfigAuthzClaimAssertions,
1197			}
1198		} else {
1199			// This authorizer always returns that the endpoint is disabled
1200			authz = &disabledAuthorizer{}
1201		}
1202		// now register with the insecure RPC server
1203		s.insecureRPCServer.Register(NewAutoConfig(s.config, s.tlsConfigurator, autoConfigBackend{Server: s}, authz))
1204	
1205		ln, err := net.ListenTCP("tcp", s.config.RPCAddr)
1206		if err != nil {
1207			return err
1208		}
1209		s.Listener = ln
1210	
1211		if s.config.NotifyListen != nil {
1212			s.config.NotifyListen()
1213		}
1214		// todo(fs): we should probably guard this
1215		if s.config.RPCAdvertise == nil {
1216			s.config.RPCAdvertise = ln.Addr().(*net.TCPAddr)
1217		}
1218	
1219		// Verify that we have a usable advertise address
1220		if s.config.RPCAdvertise.IP.IsUnspecified() {
